export const ORB_IMAGE_DESIGNS = [
  { id: 'prism-flower', label: 'Prism Flower', dataUrl: 'data:image/png;base64,' },
  { id: 'lunar-crescent', label: 'Lunar Crescent', dataUrl: 'data:image/png;base64,' },
  { id: 'starlit-ring', label: 'Starlit Ring', dataUrl: 'data:image/png;base64,' },
  { id: 'fourpetal-seal', label: 'Four-Petal Seal', dataUrl: 'data:image/png;base64,' },
] as const

export type OrbImageDesignId = typeof ORB_IMAGE_DESIGNS[number]['id']

export const ORB_IMAGE_DESIGN_URLS: Record<OrbImageDesignId, string> = Object.fromEntries(
  ORB_IMAGE_DESIGNS.map(design => [design.id, design.dataUrl]),
) as Record<OrbImageDesignId, string>
